let movies=MOVIE_DB,current=null,rank="A";
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let watched=JSON.parse(localStorage.getItem("movie.v6.watched")||"[]");
let wish=JSON.parse(localStorage.getItem("movie.v6.wish")||"[]");



function fill(el,a){el.innerHTML=a.map(x=>`<option value="${x}">${x}</option>`).join("")}
function init(){
  fill($("#category"),["すべて","ハリウッド映画","邦画","アニメ映画"]);
  fill($("#genre"),["すべて",...[...new Set(movies.flatMap(x=>x.genres))].sort()]);
  fill($("#service"),["すべて","Netflix","Disney+","Hulu","配信確認済み"]);
  ["category","genre","service"].forEach(id=>$("#"+id).addEventListener("change",updateFilterSummary));
  updateFilterSummary();render();
}
function filtered(){
  const c=$("#category").value,g=$("#genre").value,s=$("#service").value;
  return movies.filter(m=>(c==="すべて"||m.category===c)&&(g==="すべて"||m.genres.includes(g))&&(s==="すべて"||(s==="配信確認済み"?m.verified:m.services.includes(s))));
}
function updateFilterSummary(){$("#filterSummary").textContent=`現在の条件：${$("#category").value} / ${$("#genre").value} / ${$("#service").value} → ${movies.length?filtered().length:0}作品`}
function rnd(a){return a[Math.floor(Math.random()*a.length)]}



/* v6.6 — reference-quality reel renderer.
   Instead of small hand-drawn primitives, the reel symbols are sampled from the
   high-detail pixel artwork in movie-ui-clean-v614.jpeg itself. */
const reelSymbols=["popcorn","camera","clapper","star","seven","ticket","soda","glasses","chair"];
const reelAssets={};
let reelAssetsReady=false;
const EMBEDDED_REEL_ASSETS={"camera": "data:image/svg+xml;base64,", "chair": "data:image/svg+xml;base64,", "clapper": "data:image/svg+xml;base64,", "glasses": "data:image/svg+xml;base64,", "popcorn": "data:image/svg+xml;base64,", "seven": "data:image/svg+xml;base64,", "soda": "data:image/svg+xml;base64,", "star": "data:image/svg+xml;base64,", "ticket": "data:image/svg+xml;base64,"};
function preloadReelAssets(){
  return Promise.all(reelSymbols.map(name=>new Promise(resolve=>{
    const img=new Image();
    img.onload=()=>{reelAssets[name]=img;resolve();};
    img.onerror=()=>resolve();
    img.src=EMBEDDED_REEL_ASSETS[name]||"";
  }))).then(()=>{reelAssetsReady=true;});
}
const reelAssetsPromise=preloadReelAssets();

function reelCanvas(el){
  let c=el.querySelector("canvas");
  if(!c){c=document.createElement("canvas");c.width=240;c.height=540;el.innerHTML="";el.appendChild(c);}
  return c;
}
function drawAssetSymbol(g,type,cx,cy,target=128){
  const img=reelAssets[type];
  if(!img)return;
  g.save();
  g.imageSmoothingEnabled=false;
  const sc=Math.min(target/img.naturalWidth,target/img.naturalHeight);
  const w=target,h=target;
  g.drawImage(img,cx-w/2,cy-h/2,w,h);
  g.restore();
}
function drawReel(el,symbols){
  const c=reelCanvas(el),g=c.getContext("2d"),W=c.width,H=c.height;
  g.clearRect(0,0,W,H);
  const grad=g.createLinearGradient(0,0,W,0);
  grad.addColorStop(0,"#9a743c");grad.addColorStop(.08,"#e4c783");grad.addColorStop(.25,"#fff0bf");
  grad.addColorStop(.5,"#fff8d8");grad.addColorStop(.75,"#f1d79b");grad.addColorStop(.93,"#c39a58");grad.addColorStop(1,"#795126");
  g.fillStyle=grad;g.fillRect(0,0,W,H);
  g.fillStyle="rgba(255,255,255,.35)";g.fillRect(15,5,8,H-10);
  g.fillStyle="rgba(50,25,8,.18)";g.fillRect(W-24,5,9,H-10);
  g.fillStyle="#76502c";g.fillRect(0,178,W,4);g.fillRect(0,358,W,4);
  g.fillStyle="#e2c27d";g.fillRect(0,182,W,2);g.fillRect(0,362,W,2);
  [90,270,450].forEach((cy,i)=>drawAssetSymbol(g,symbols[i],W/2,cy,132));
}
function randomStack(){return [rnd(reelSymbols),rnd(reelSymbols),rnd(reelSymbols)]}


/* v6.10 — real slot winning patterns.
   Each reel array is [top, middle, bottom]. */
const SLOT_WIN_PATTERNS=[
  {name:"CENTER", rows:[1,1,1]},
  {name:"TOP", rows:[0,0,0]},
  {name:"BOTTOM", rows:[2,2,2]},
  {name:"DIAGONAL_DOWN", rows:[0,1,2]},
  {name:"DIAGONAL_UP", rows:[2,1,0]},
  {name:"V_SHAPE", rows:[0,2,0]},
  {name:"INVERTED_V", rows:[2,0,2]}
];

function makeWinningFinals(){
  const pattern=rnd(SLOT_WIN_PATTERNS);
  const winningSymbol=rnd(reelSymbols);
  const finals=[randomStack(),randomStack(),randomStack()];

  // Put the same winning symbol on the selected payline.
  pattern.rows.forEach((row,reelIndex)=>{
    finals[reelIndex][row]=winningSymbol;
  });

  // Avoid fillers accidentally becoming another obvious 3-of-a-kind.
  for(let row=0;row<3;row++){
    if(pattern.rows[0]===row && pattern.rows[1]===row && pattern.rows[2]===row) continue;
    const seen=new Set();
    for(let reel=0;reel<3;reel++){
      if(pattern.rows[reel]===row) continue;
      let sym=finals[reel][row], guard=0;
      while(seen.has(sym) && guard++<20) sym=rnd(reelSymbols);
      finals[reel][row]=sym;
      seen.add(sym);
    }
  }

  return {pattern,winningSymbol,finals};
}

function playWinEffect(){
  const overlay=$("#spinOverlay");
  overlay.classList.remove("win-glow");
  void overlay.offsetWidth;
  overlay.classList.add("win-glow");
  setTimeout(()=>overlay.classList.remove("win-glow"),2600);
}

function spin(){
  const pool=filtered();
  if(!pool.length){
    alert("この条件に合う作品がありません。ジャンル選択で条件を広げてください。");
    return;
  }

  const overlay=$("#spinOverlay");
  const reels=[$("#mr1"),$("#mr2"),$("#mr3")];

  // Keep the reel layer visible permanently after the first spin.
  overlay.classList.remove("hidden","win-glow");
  $("#dynamicResult").classList.add("hidden");

  const begin=()=>{
    reels.forEach(r=>{
      r.classList.add("spinning");
      drawReel(r,randomStack());
    });

    let tick=0;
    const timer=setInterval(()=>{
      reels.forEach((r,i)=>{
        const stopAt=27+i*7;
        if(tick<stopAt) drawReel(r,randomStack());
      });
      tick++;

      if(tick>44){
        clearInterval(timer);
        current=rnd(pool);

        const win=makeWinningFinals();

        // Stop left -> center -> right and KEEP the final symbols on screen.
        reels.forEach((r,i)=>setTimeout(()=>{
          r.classList.remove("spinning");
          drawReel(r,win.finals[i]);

          r.animate(
            [
              {transform:"translateY(-8px)",filter:"brightness(1.45)"},
              {transform:"translateY(3px)",filter:"brightness(1.12)"},
              {transform:"translateY(0)",filter:"brightness(1)"}
            ],
            {duration:240,easing:"steps(5,end)"}
          );

          if(i===2){
            setTimeout(()=>{
              playWinEffect();
              show(current);
              // IMPORTANT: do not hide spinOverlay here.
              // The winning reel result remains visible until the next SPIN.
            },260);
          }
        },i*300));
      }
    },62);
  };

  if(reelAssetsReady) begin();
  else reelAssetsPromise.then(begin);
}

function show(m){
  $("#title").textContent=m.title;$("#yearText").textContent=m.year?`(${m.year})`:"";
  $("#tags").innerHTML=[...m.genres,m.category].map(x=>`<span class="tag">${x}</span>`).join("");
  $("#hook").textContent=makeSynopsis(m);$("#services").innerHTML=serviceHtml(m);
  $("#wish").textContent=wish.some(x=>x.title===m.title)?"★ 観たい済み":"☆ 観たい";
  $("#flavor").textContent=flavorText(m);drawPoster(m);$("#dynamicResult").classList.remove("hidden");
}
function serviceHtml(m){
  if(!m.services.length)return `<span class="unknown-service">配信先：未確認</span>`;
  return m.services.map(s=>{const cls=s==="Netflix"?"netflix":s==="Disney+"?"disney":"hulu";const mark=s==="Netflix"?"N":s==="Disney+"?"Disney+":"hulu";return `<div class="service-card"><div class="service-logo ${cls}">${mark}</div><div class="service-text"><b>${s}</b><span>配信中</span></div></div>`}).join("");
}
function makeSynopsis(m){
  const t=m.title,g=m.genres;
  if(t.includes("ワイルド・スピード"))return "ストリートレースで出会った、正反対の二人。スピードで繋がった絆が、やがて大きな運命を動かしていく。";
  if(t.includes("タイタニック"))return "巨大客船で出会った二人。短くも鮮烈な恋と、歴史に残る夜を壮大なスケールで描く。";
  if(t.includes("ハリー・ポッター"))return "魔法と秘密に満ちた学園で、少年たちの冒険が始まる。幻想的な世界へ一気に浸りたい夜に。";
  if(g.includes("アクション"))return `勢いと緊張感を楽しめる『${t}』。今日は派手な一本を観たい夜に。`;
  if(g.includes("恋愛"))return `人と人の距離や気持ちの揺れを描く『${t}』。少し感情に浸りたい夜に。`;
  if(g.includes("ホラー"))return `不穏な空気と緊張感を味わう『${t}』。部屋を暗くして観る一本。`;
  if(g.includes("コメディ"))return `気軽に笑って楽しめる『${t}』。難しいことは考えずに観たい日に。`;
  if(g.includes("感動"))return `観終わったあとまで余韻が残る『${t}』。じっくり一本観たい夜に。`;
  return `${g[0]}を軸に楽しめる『${t}』。今日の気分に合えば、そのまま一本決めたい候補。`;
}
function flavorText(m){
  if(m.genres.includes("カー"))return "スピードが、すべてを変えていく——！";
  if(m.genres.includes("アクション"))return "今日は派手にいこう。ポップコーンを忘れずに。";
  if(m.genres.includes("恋愛"))return "エンドロールまで、少しだけ余韻に浸ろう。";
  if(m.genres.includes("ホラー"))return "電気を消すかどうかは、あなた次第。";
  return "映画は、選ぶ時間からもう始まってる。";
}

/* richer poster canvas */

/* v6.2 — 300-title deterministic pixel-poster renderer.
   Every title gets a stable composition generated from its own title/id/year/category/genres.
   It does not reuse one generic city silhouette. */
function hash32(s){
  let h=2166136261>>>0;
  for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}
  return h>>>0;
}
function rng(seed){return function(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296}}
function px(ctx,x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function linePx(ctx,x0,y0,x1,y1,c,w=1){
  ctx.strokeStyle=c;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(Math.round(x0)+.5,Math.round(y0)+.5);ctx.lineTo(Math.round(x1)+.5,Math.round(y1)+.5);ctx.stroke()
}
function paletteFor(m,r){
  const gs=m.genres.join("/");
  if(gs.includes("ホラー"))return ["#080a12","#1d1830","#6b2037","#e9c26a","#d7e6df","#a33445"];
  if(gs.includes("恋愛"))return ["#18243b","#a94f67","#f0a07b","#ffd6a5","#4b1f38","#f4e8cf"];
  if(gs.includes("SF"))return ["#071426","#123a5a","#1f7590","#71d4d7","#f0c95b","#e8eef0"];
  if(gs.includes("アクション")||gs.includes("カー"))return ["#10172b","#263a5a","#c33c35","#f08b3d","#f2cf67","#dce8ef"];
  if(gs.includes("ファンタジー"))return ["#101a2e","#263e55","#5b4777","#e6b94e","#83bfa8","#e9dfc6"];
  if(gs.includes("コメディ"))return ["#192944","#35658b","#e5a742","#e06b4f","#f1dc8b","#f5eee0"];
  if(m.category==="アニメ映画")return ["#172b45","#356b86","#d85b62","#efad58","#f4db8e","#f2eee0"];
  return ["#111a28","#2d4052","#774351","#c8764e","#d8b96d","#ece2c8"];
}
function drawSky(ctx,p,r){
  px(ctx,0,0,120,176,p[0]);px(ctx,0,38,120,70,p[1]);px(ctx,0,78,120,98,p[2]);
  for(let i=0;i<34;i++){let x=Math.floor(r()*118),y=4+Math.floor(r()*74),s=r()>.82?2:1;px(ctx,x,y,s,s,r()>.25?p[3]:p[5])}
}
function drawCity(ctx,p,r,horizon=124){
  for(let x=-3;x<123;){
    let w=5+Math.floor(r()*11),h=12+Math.floor(r()*47);
    px(ctx,x,horizon-h,w,h,p[0]);
    if(r()>.4)for(let yy=horizon-h+5;yy<horizon-4;yy+=7)if(r()>.45)px(ctx,x+2,yy,1,2,p[3]);
    x+=w+1;
  }
}
function drawRoad(ctx,p,r){
  px(ctx,0,120,120,56,"#11131b");px(ctx,55,120,10,56,"#222632");
  for(let y=127;y<176;y+=15)px(ctx,59,y,2,8,p[3]);
  linePx(ctx,0,176,46,120,p[4],2);linePx(ctx,119,176,74,120,p[4],2)
}
function drawCar2(ctx,x,y,scale,body,glass){
  px(ctx,x,y,40*scale,9*scale,body);px(ctx,x+8*scale,y-8*scale,24*scale,9*scale,body);
  px(ctx,x+11*scale,y-6*scale,8*scale,4*scale,glass);px(ctx,x+21*scale,y-6*scale,8*scale,4*scale,glass);
  px(ctx,x+5*scale,y+7*scale,8*scale,6*scale,"#08090c");px(ctx,x+27*scale,y+7*scale,8*scale,6*scale,"#08090c");
  px(ctx,x+2*scale,y+2*scale,3*scale,3*scale,"#ffe59b");px(ctx,x+35*scale,y+2*scale,3*scale,3*scale,"#ff7059");
}
function drawFigures(ctx,p,r,count=2){
  for(let i=0;i<count;i++){
    let x=27+i*(66/(Math.max(1,count-1)))+Math.floor(r()*5-2), y=110+Math.floor(r()*8);
    px(ctx,x,y-27,8,8,p[5]);px(ctx,x+1,y-19,6,19,p[0]);px(ctx,x-3,y-15,4,15,p[0]);px(ctx,x+7,y-15,4,15,p[0]);
    px(ctx,x+1,y,2,19,p[0]);px(ctx,x+5,y,2,19,p[0]);
  }
}
function drawShip(ctx,p,r){
  px(ctx,8,119,104,9,p[5]);px(ctx,22,108,73,12,p[4]);px(ctx,33,99,51,10,p[5]);
  for(let i=0;i<4;i++){px(ctx,37+i*13,88,5,12,p[0]);px(ctx,38+i*13,86,3,3,p[3])}
  px(ctx,14,128,93,4,p[0]);
}
function drawCastle(ctx,p,r){
  px(ctx,22,91,76,42,p[0]);
  for(let i=0;i<5;i++){let x=27+i*14,h=22+(i%2)*13;px(ctx,x,91-h,9,h,p[0]);px(ctx,x+2,91-h-6,5,6,p[0]);px(ctx,x+3,91-h+5,2,4,p[3])}
  px(ctx,55,72,10,61,p[0]);px(ctx,58,82,3,5,p[3]);
}
function drawSpace(ctx,p,r){
  let cx=60,cy=87;px(ctx,cx-4,cy-31,8,44,p[5]);px(ctx,cx-13,cy-16,26,7,p[5]);px(ctx,cx-8,cy+10,16,17,p[4]);
  px(ctx,cx-3,cy-37,6,8,p[3]);for(let i=0;i<5;i++)px(ctx,cx-2+i,cy+27+i*4,4-i%2,5,p[3]);
}
function drawMonster(ctx,p,r){
  px(ctx,39,73,42,51,p[0]);px(ctx,31,87,12,31,p[0]);px(ctx,77,84,13,34,p[0]);
  px(ctx,45,65,8,10,p[0]);px(ctx,68,65,8,10,p[0]);px(ctx,50,84,4,3,p[3]);px(ctx,68,84,4,3,p[3]);
  for(let i=0;i<5;i++)px(ctx,43+i*8,118+i%2*5,5,17,p[0]);
}
function drawMystery(ctx,p,r){
  drawCity(ctx,p,r,128);px(ctx,50,73,20,46,p[0]);px(ctx,45,76,30,4,p[0]);px(ctx,52,64,16,12,p[0]);
  px(ctx,57,82,3,3,p[3]);px(ctx,64,82,3,3,p[3]);
}
function drawTitleBlock(ctx,m,p){
  // Original title treatment: deliberately not reproducing official poster typography/logos.
  px(ctx,7,7,106,30,"#080a12");ctx.strokeStyle=p[3];ctx.lineWidth=1;ctx.strokeRect(8.5,8.5,103,27);
  ctx.textAlign="center";ctx.fillStyle=p[5];ctx.font="bold 7px monospace";
  let s=m.title, lines=[];
  while(s.length){lines.push(s.slice(0,15));s=s.slice(15);if(lines.length===2)break}
  ctx.fillText(lines[0]||"",60,20);if(lines[1])ctx.fillText(lines[1],60,29);
  ctx.fillStyle=p[3];ctx.font="bold 4px monospace";ctx.fillText(`${m.year||""}  ${m.genres[0]||""}`,60,34);
}

/* v6.5 — image-backed poster pixelation engine.
   If m.posterSource is set, the source artwork is converted client-side into a high-quality
   pixel-art poster using nearest-neighbor scaling, palette reduction, contrast shaping,
   and Bayer dithering. If no source is present, the previous generated poster is used. */
async function drawPoster(m){
  const host=$("#pixelPoster"); host.innerHTML="";
  const poster=document.createElement("canvas");
  poster.width=160; poster.height=240;
  host.appendChild(poster);
  const out=poster.getContext("2d"); out.imageSmoothingEnabled=false;

  if(m.posterSource){
    try{
      const img=await loadPosterImage(m.posterSource);
      renderPixelPosterFromImage(out,img,m);
      return;
    }catch(err){
      console.warn("posterSource failed, fallback:",m.title,err);
    }
  }
  drawFallbackPoster(out,m);
}

function loadPosterImage(src){
  return new Promise((resolve,reject)=>{
    const img=new Image();
    img.crossOrigin="anonymous";
    img.onload=()=>resolve(img);
    img.onerror=reject;
    img.src=src;
  });
}

function renderPixelPosterFromImage(out,img,m){
  const LOW_W=80, LOW_H=120;
  const low=document.createElement("canvas");
  low.width=LOW_W; low.height=LOW_H;
  const g=low.getContext("2d",{willReadFrequently:true});
  g.imageSmoothingEnabled=true;

  // cover crop while preserving composition
  const srcRatio=img.width/img.height, dstRatio=LOW_W/LOW_H;
  let sx=0,sy=0,sw=img.width,sh=img.height;
  if(srcRatio>dstRatio){ sw=img.height*dstRatio; sx=(img.width-sw)/2; }
  else { sh=img.width/dstRatio; sy=(img.height-sh)/2; }
  g.drawImage(img,sx,sy,sw,sh,0,0,LOW_W,LOW_H);

  const data=g.getImageData(0,0,LOW_W,LOW_H);
  const d=data.data;
  const bayer=[
    [0,8,2,10],
    [12,4,14,6],
    [3,11,1,9],
    [15,7,13,5]
  ];
  // 6x6x6 palette + soft film contrast and ordered dithering.
  for(let y=0;y<LOW_H;y++){
    for(let x=0;x<LOW_W;x++){
      const i=(y*LOW_W+x)*4;
      let r=d[i],gg=d[i+1],b=d[i+2];

      // cinematic contrast
      r=(r-128)*1.12+128;
      gg=(gg-128)*1.10+128;
      b=(b-128)*1.14+128;

      // mild saturation
      const lum=.299*r+.587*gg+.114*b;
      r=lum+(r-lum)*1.12; gg=lum+(gg-lum)*1.12; b=lum+(b-lum)*1.12;

      // ordered dithering before quantization
      const t=(bayer[y&3][x&3]-7.5)*2.2;
      r+=t;gg+=t;b+=t;

      const q=v=>Math.max(0,Math.min(255,Math.round(v/51)*51));
      d[i]=q(r);d[i+1]=q(gg);d[i+2]=q(b);
    }
  }
  g.putImageData(data,0,0);

  // nearest-neighbor upscale to final canvas
  out.clearRect(0,0,160,240);
  out.imageSmoothingEnabled=false;
  out.drawImage(low,0,0,160,240);

  // subtle film-frame treatment
  out.fillStyle="rgba(8,7,10,.92)";
  out.fillRect(0,0,6,240);out.fillRect(154,0,6,240);
  out.fillStyle="#d8b766";
  for(let y=8;y<232;y+=14){out.fillRect(1,y,3,7);out.fillRect(156,y,3,7);}
}

function drawFallbackPoster(out,m){
  // clean fallback when a source image is not configured.
  const seed=hash32(`${m.id}|${m.title}|${m.year}|${m.category}|${m.genres.join(",")}`), r=rng(seed), p=paletteFor(m,r);
  out.save();
  out.scale(160/120,240/176);
  drawSky(out,p,r);
  const g=m.genres.join("/"),t=m.title;
  if(t.includes("タイタニック")) drawShip(out,p,r);
  else if(t.includes("ハリー・ポッター")) drawCastle(out,p,r);
  else if(g.includes("カー")){drawCity(out,p,r,118);drawRoad(out,p,r);drawCar2(out,12,139,.95,p[3],p[4]);drawCar2(out,67,145,.88,p[5],p[4]);}
  else if(g.includes("怪獣")){drawCity(out,p,r,132);drawMonster(out,p,r);}
  else if(g.includes("SF")){drawSpace(out,p,r);if(r()>.45)drawCity(out,p,r,139);}
  else if(g.includes("恋愛")){drawCity(out,p,r,132);drawFigures(out,p,r,2);}
  else if(g.includes("ミステリー")||g.includes("犯罪")) drawMystery(out,p,r);
  else if(g.includes("アクション")){drawCity(out,p,r,127);drawFigures(out,p,r,1);}
  else {drawCity(out,p,r,130);drawFigures(out,p,r,1+(seed%3));}
  drawTitleBlock(out,m,p);
  out.restore();
}

function saveAll(){localStorage.setItem("movie.v6.watched",JSON.stringify(watched));localStorage.setItem("movie.v6.wish",JSON.stringify(wish));render()}
function esc(s){return String(s||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function render(){
  $("#wishCount").textContent=wish.length;$("#watchedCount").textContent=watched.length;
  const hb=$("#homeWishBadge");
  if(hb){
    hb.textContent=String(wish.length);
    hb.classList.toggle("hidden",wish.length===0);
    hb.setAttribute("aria-label",`観たいリスト ${wish.length}件`);
  }
  $("#watchList").innerHTML=wish.length?wish.map((m,i)=>`<div class="card"><b>${esc(m.title)}</b><br><small>${esc(m.category)} / ${m.genres.map(esc).join("・")}</small><div class="card-actions"><button onclick="reviewWish(${i})">✓ 観た</button><button onclick="removeWish(${i})">削除</button></div></div>`).join(""):"<div class='card'>まだありません。</div>";
  $("#historyList").innerHTML=watched.length?watched.map(m=>`<div class="card"><b>${esc(m.title)}</b> <span class="tag">${m.rank}</span><br><small>${esc(m.category)} / ${esc(m.date)}</small>${m.memo?`<p>${esc(m.memo)}</p>`:""}</div>`).join(""):"<div class='card'>まだありません。</div>";
}
$("#spin").onclick=spin;$("#again").onclick=spin;
$("#wish").onclick=()=>{if(!current)return;wish.some(x=>x.title===current.title)?wish=wish.filter(x=>x.title!==current.title):wish.unshift(current);saveAll();show(current)};
$("#watched").onclick=()=>openReview(current);$("#applyFilters").onclick=()=>switchTab("home");
function openReview(m){if(!m)return;current=m;rank="A";$("#reviewTitle").textContent=`「${m.title}」の評価`;$("#memo").value="";$$(".ranks button").forEach(b=>b.classList.toggle("active",b.textContent==="A"));$("#modal").classList.remove("hidden")}
window.reviewWish=i=>openReview(wish[i]);window.removeWish=i=>{wish.splice(i,1);saveAll()};
$$(".ranks button").forEach(b=>b.onclick=()=>{rank=b.textContent;$$(".ranks button").forEach(x=>x.classList.toggle("active",x===b))});
$("#cancel").onclick=()=>$("#modal").classList.add("hidden");$("#save").onclick=()=>{watched=watched.filter(x=>x.title!==current.title);watched.unshift({...current,rank,memo:$("#memo").value.trim(),date:new Date().toLocaleDateString("ja-JP")});wish=wish.filter(x=>x.title!==current.title);$("#modal").classList.add("hidden");saveAll()};
function switchTab(id){
  const target=$("#"+id);
  if(!target){console.error("screen not found:",id);return;}
  $$(".screen").forEach(x=>x.classList.remove("active"));
  target.classList.add("active");
  $$(".app-nav-button").forEach(b=>b.classList.toggle("active",b.dataset.tab===id));
  window.scrollTo({top:0,behavior:"smooth"});
}
$$(".app-nav-button").forEach(b=>{
  b.addEventListener("click",e=>{
    e.preventDefault();
    switchTab(b.dataset.tab);
  });
});
$("#clearData").onclick=()=>{if(confirm("視聴履歴と観たいリストをすべて削除しますか？")){watched=[];wish=[];saveAll()}};

// v6.1: embedded database startup — no fetch/CORS dependency
init();

// v6.2 explicit home buttons on Watch List / History
$$("[data-go-home]").forEach(b=>b.addEventListener("click",()=>switchTab("home")));

// v6.6: prepare the reference-quality reels.
requestAnimationFrame(()=>{
  const paint=()=>{
    const a=$("#mr1"),b=$("#mr2"),c=$("#mr3");
    if(a&&b&&c){
      drawReel(a,["popcorn","camera","clapper"]);
      drawReel(b,["star","seven","ticket"]);
      drawReel(c,["soda","glasses","chair"]);
    }
  };
  if(reelAssetsReady) paint(); else reelAssetsPromise.then(paint);
});

// v6.5 poster-source map importer.
// Usage from console or future settings UI:
// applyPosterSourceMap({"1":"posters/001.jpg","2":"posters/002.jpg", ...})
function applyPosterSourceMap(map){
  movies.forEach(m=>{const v=map[m.id]||map[String(m.id)]||map[m.title]; if(v)m.posterSource=v;});
  localStorage.setItem("movie.v6.5.posterSources",JSON.stringify(map));
}
try{
  const saved=JSON.parse(localStorage.getItem("movie.v6.5.posterSources")||"{}");
  movies.forEach(m=>{const v=saved[m.id]||saved[String(m.id)]||saved[m.title]; if(v)m.posterSource=v;});
}catch(e){}


// v6.7 runtime self-test: catches missing IDs before the user hits a dead button.
function runMovieSelfTest(){
  const required=[
    "spin","dynamicResult","mr1","mr2","mr3",
    "category","genre","service","filterSummary","applyFilters",
    "watchList","historyList","wishCount","watchedCount",
    "clearData","modal","cancel","save"
  ];
  const missing=required.filter(id=>!document.getElementById(id));
  const screens=["home","genres","watch","history","settings"].filter(id=>!document.getElementById(id));
  const result={
    ok:missing.length===0&&screens.length===0&&Array.isArray(movies)&&movies.length===300,
    missing,
    missingScreens:screens,
    movieCount:Array.isArray(movies)?movies.length:0
  };
  if(!result.ok)console.error("MOVIE SELF TEST FAILED",result);
  else console.info("MOVIE SELF TEST OK",result);
  return result;
}
window.MOVIE_SELF_TEST=runMovieSelfTest;
requestAnimationFrame(runMovieSelfTest);
